insert into public.words (id, word, romanization, category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, likes, saves, translations) values
('259', '숲세권', 'Sup-Se-Gwon', 'new-slang', '숲·공원이 걸어갈 거리에 있는 동네', '{"en": "A neighbourhood within walking distance of woods or a park", "ja": "森や公園が徒歩圏にある町", "es": "Un barrio a pie de un bosque o parque", "vi": "Khu ở gần rừng cây hay công viên", "de": "Ein Viertel in Gehweite von Wald oder Park"}'::jsonb, '[숩쎄꿘]', '[{"type": "명사", "definition": "숲이나 큰 공원이 걸어갈 거리에 있어 공기와 산책 환경이 좋은 주거지. 아파트 분양 광고가 녹지 프리미엄을 내세울 때 특히 자주 쓴다.", "definition_i18n": {"en": "A home close enough to woods or a big park to walk there — clean air, somewhere to stroll. Property ads lean on it hardest when selling a green premium.", "ja": "森や大きな公園が徒歩圏にあり、空気と散歩環境がよい住まい。マンション分譲広告が緑地プレミアムを打ち出すときに特によく使う。", "es": "Una vivienda lo bastante cerca de un bosque o un gran parque para ir andando: buen aire y sitio para pasear. Los anuncios inmobiliarios lo usan para vender la prima verde.", "vi": "Chỗ ở đủ gần rừng cây hay công viên lớn để đi bộ tới — không khí trong lành, có chỗ dạo. Quảng cáo bất động sản hay dùng để bán \"phí xanh\".", "de": "Eine Wohnlage nah genug an Wald oder großem Park, um hinzulaufen — gute Luft, Platz zum Spazieren. Immobilienanzeigen werben damit für den Grün-Aufschlag."}, "examples": [{"kor": "여기 숲세권이라 아침마다 산책 나가.", "eng": "This place is 숲세권 — I go for a walk every morning.", "ja": "ここは숲세권だから毎朝散歩に行く。", "es": "Esto es 숲세권: salgo a caminar cada mañana.", "vi": "Ở đây là 숲세권 nên sáng nào tôi cũng đi dạo.", "de": "Hier ist 숲세권 — ich gehe jeden Morgen spazieren."}]}]'::jsonb, '''역세권''(지하철역 도보권)에서 ''-세권''만 떨어져 나와 접미사처럼 쓰이며 만들어진 부동산·생활 신조어 계열의 하나로, 앞에 숲·큰 공원을 붙인 말이다. 2010년대 후반 분양 마케팅과 언론 보도를 타고 계열 전체가 퍼졌고, 개별 단어의 최초 사용처는 확인되지 않는다.', '{"en": "One of the ''-세권'' family: 역세권 (''within walking distance of a subway station'') shed its ending, which now works as a suffix you attach to whatever matters nearby — here, woods or a large park. The family spread through late-2010s property marketing and news coverage; no first use is documented for the individual word.", "ja": "「역세권(駅の徒歩圏)」から「-세권」だけが切り離され接尾辞のように使われる不動産・生活新造語の一つで、前に森や大きな公園を付けた形。2010年代後半の分譲マーケティングと報道を通じて系列全体が広まり、個別の語の初出は確認されていない。", "es": "Uno de la familia ''-세권'': de 역세권 (''a poca distancia a pie del metro'') se desprendió la terminación, que ahora funciona como sufijo al que se antepone lo que importa cerca — aquí, un bosque o un gran parque. La familia se difundió con el marketing inmobiliario y la prensa de finales de los 2010; no se documenta el primer uso de cada palabra.", "vi": "Một từ trong họ ''-세권'': từ 역세권 (''trong tầm đi bộ tới ga tàu điện''), đuôi -세권 tách ra thành hậu tố gắn với tiện ích người ta quan tâm — ở đây là rừng cây hoặc công viên lớn. Cả họ từ lan rộng nhờ marketing bất động sản và báo chí cuối thập niên 2010; không xác định được lần dùng đầu tiên của từng từ.", "de": "Eines der ''-세권''-Wörter: Von 역세권 (''in Gehweite einer U-Bahn-Station'') löste sich die Endung und dient nun als Suffix, dem man die jeweils wichtige Einrichtung voranstellt — hier Wald oder ein großer Park. Die Wortfamilie verbreitete sich über Immobilienmarketing und Presse der späten 2010er; der Erstgebrauch einzelner Wörter ist nicht belegt."}'::jsonb, '부동산 매물 소개와 아파트 분양 광고에서 입지 장점을 한마디로 보여줄 때 쓰고, 일상 대화에서도 ''여기 숲세권이야''처럼 쓴다. 같은 계열 단어가 계속 만들어지고 있어, 뜻을 모르면 앞 글자가 무엇의 준말인지부터 보면 된다.', '{"en": "Used in property listings and new-build ads to sum up a location in one word, and in everyday talk too: ''여기 숲세권이야'' (''this place is 숲세권''). New members of the family keep appearing — when you meet one, work out what the first syllable is short for.", "ja": "不動産の物件紹介やマンション分譲広告で立地の強みを一言で示すときに使い、日常会話でも「ここは숲세권だ」のように使う。同系列の語が次々に作られるので、意味が分からないときはまず頭の字が何の略かを見ればよい。", "es": "Se usa en anuncios de pisos y de obra nueva para resumir la ubicación en una palabra, y también al hablar: ''esto es 숲세권''. La familia no para de crecer: ante una nueva, mira de qué es abreviatura la primera sílaba.", "vi": "Dùng trong tin rao bất động sản và quảng cáo chung cư mới để gói gọn vị trí trong một từ, và cả trong nói chuyện: ''chỗ này là 숲세권''. Họ từ này liên tục có thành viên mới — gặp từ lạ thì cứ xem âm đầu viết tắt cho cái gì.", "de": "Steht in Immobilienanzeigen und Neubauwerbung, um die Lage in einem Wort zu fassen, und ebenso im Alltag: ''hier ist 숲세권''. Die Wortfamilie wächst ständig — bei einem neuen Wort schaut man, wofür die erste Silbe steht."}'::jsonb, array['슬세권','편세권','스세권'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Forest zone (near woods or a park)"}, {"lang": "🇯🇵 JA", "text": "森が近い住宅地"}, {"lang": "🇨🇳 ZH", "text": "林荫住宅区(近森林公园)"}, {"lang": "🇻🇳 VI", "text": "Khu gần rừng/công viên"}, {"lang": "🇪🇸 ES", "text": "Zona de bosque (cerca de parque)"}, {"lang": "🇩🇪 DE", "text": "Waldnähe-Viertel"}]'::jsonb),
('260', '편세권', 'Pyeon-Se-Gwon', 'new-slang', '편의점이 코앞인 동네', '{"en": "A neighbourhood with a convenience store right there", "ja": "コンビニが目の前にある町", "es": "Un barrio con la tienda 24 h al lado", "vi": "Khu có cửa hàng tiện lợi ngay cạnh", "de": "Ein Viertel mit dem Kiosk direkt vor der Tür"}'::jsonb, '[편세꿘]', '[{"type": "명사", "definition": "24시간 편의점이 바로 옆에 있어 필요한 걸 언제든 사 올 수 있는 주거지. 1인 가구가 집을 고를 때 실제로 따지는 조건이라 매물 소개에도 자주 붙는다.", "definition_i18n": {"en": "A home with a 24-hour convenience store next door, so you can grab what you need at any hour. Single-person households actually weigh this when flat-hunting, so listings advertise it.", "ja": "24時間営業のコンビニがすぐ隣にあり、必要なものをいつでも買える住まい。一人暮らしが物件選びで実際に重視する条件で、募集広告にもよく載る。", "es": "Una vivienda con tienda 24 h al lado, para comprar lo que haga falta a cualquier hora. Los hogares unipersonales lo tienen en cuenta de verdad, y los anuncios lo destacan.", "vi": "Chỗ ở có cửa hàng tiện lợi 24/7 ngay bên cạnh, cần gì mua lúc nào cũng được. Người ở một mình thật sự cân nhắc điều này khi tìm nhà nên tin rao cũng ghi.", "de": "Eine Wohnung mit 24-Stunden-Kiosk nebenan — man bekommt jederzeit, was man braucht. Für Single-Haushalte ein echtes Kriterium, deshalb steht es in Inseraten."}, "examples": [{"kor": "편세권이라 야식 사러 30초면 돼.", "eng": "It''s 편세권 — a midnight snack run takes 30 seconds.", "ja": "편세권だから夜食を買いに30秒で行ける。", "es": "Es 편세권: bajar a por algo de noche son 30 segundos.", "vi": "Là 편세권 nên đi mua đồ ăn khuya mất 30 giây.", "de": "편세권 — der Weg zum Mitternachtssnack dauert 30 Sekunden."}]}]'::jsonb, '''역세권''(지하철역 도보권)에서 ''-세권''만 떨어져 나와 접미사처럼 쓰이며 만들어진 부동산·생활 신조어 계열의 하나로, 앞에 편의점을 붙인 말이다. 2010년대 후반 분양 마케팅과 언론 보도를 타고 계열 전체가 퍼졌고, 개별 단어의 최초 사용처는 확인되지 않는다.', '{"en": "One of the ''-세권'' family: 역세권 (''within walking distance of a subway station'') shed its ending, which now works as a suffix you attach to whatever matters nearby — here, a convenience store. The family spread through late-2010s property marketing and news coverage; no first use is documented for the individual word.", "ja": "「역세권(駅の徒歩圏)」から「-세권」だけが切り離され接尾辞のように使われる不動産・生活新造語の一つで、前にコンビニを付けた形。2010年代後半の分譲マーケティングと報道を通じて系列全体が広まり、個別の語の初出は確認されていない。", "es": "Uno de la familia ''-세권'': de 역세권 (''a poca distancia a pie del metro'') se desprendió la terminación, que ahora funciona como sufijo al que se antepone lo que importa cerca — aquí, una tienda de conveniencia. La familia se difundió con el marketing inmobiliario y la prensa de finales de los 2010; no se documenta el primer uso de cada palabra.", "vi": "Một từ trong họ ''-세권'': từ 역세권 (''trong tầm đi bộ tới ga tàu điện''), đuôi -세권 tách ra thành hậu tố gắn với tiện ích người ta quan tâm — ở đây là cửa hàng tiện lợi. Cả họ từ lan rộng nhờ marketing bất động sản và báo chí cuối thập niên 2010; không xác định được lần dùng đầu tiên của từng từ.", "de": "Eines der ''-세권''-Wörter: Von 역세권 (''in Gehweite einer U-Bahn-Station'') löste sich die Endung und dient nun als Suffix, dem man die jeweils wichtige Einrichtung voranstellt — hier ein Convenience Store. Die Wortfamilie verbreitete sich über Immobilienmarketing und Presse der späten 2010er; der Erstgebrauch einzelner Wörter ist nicht belegt."}'::jsonb, '부동산 매물 소개와 아파트 분양 광고에서 입지 장점을 한마디로 보여줄 때 쓰고, 일상 대화에서도 ''여기 편세권이야''처럼 쓴다. 같은 계열 단어가 계속 만들어지고 있어, 뜻을 모르면 앞 글자가 무엇의 준말인지부터 보면 된다.', '{"en": "Used in property listings and new-build ads to sum up a location in one word, and in everyday talk too: ''여기 편세권이야'' (''this place is 편세권''). New members of the family keep appearing — when you meet one, work out what the first syllable is short for.", "ja": "不動産の物件紹介やマンション分譲広告で立地の強みを一言で示すときに使い、日常会話でも「ここは편세권だ」のように使う。同系列の語が次々に作られるので、意味が分からないときはまず頭の字が何の略かを見ればよい。", "es": "Se usa en anuncios de pisos y de obra nueva para resumir la ubicación en una palabra, y también al hablar: ''esto es 편세권''. La familia no para de crecer: ante una nueva, mira de qué es abreviatura la primera sílaba.", "vi": "Dùng trong tin rao bất động sản và quảng cáo chung cư mới để gói gọn vị trí trong một từ, và cả trong nói chuyện: ''chỗ này là 편세권''. Họ từ này liên tục có thành viên mới — gặp từ lạ thì cứ xem âm đầu viết tắt cho cái gì.", "de": "Steht in Immobilienanzeigen und Neubauwerbung, um die Lage in einem Wort zu fassen, und ebenso im Alltag: ''hier ist 편세권''. Die Wortfamilie wächst ständig — bei einem neuen Wort schaut man, wofür die erste Silbe steht."}'::jsonb, array['슬세권','숲세권','스세권'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Convenience-store zone"}, {"lang": "🇯🇵 JA", "text": "コンビニが近い住宅地"}, {"lang": "🇨🇳 ZH", "text": "便利店住宅区"}, {"lang": "🇻🇳 VI", "text": "Khu gần cửa hàng tiện lợi"}, {"lang": "🇪🇸 ES", "text": "Zona de tienda 24 h"}, {"lang": "🇩🇪 DE", "text": "Kiosk-Viertel"}]'::jsonb),
('261', '스세권', 'Seu-Se-Gwon', 'new-slang', '스타벅스가 걸어갈 거리인 동네', '{"en": "A neighbourhood with a Starbucks in walking distance", "ja": "スタバが徒歩圏にある町", "es": "Un barrio con Starbucks a pie", "vi": "Khu có Starbucks trong tầm đi bộ", "de": "Ein Viertel mit Starbucks in Gehweite"}'::jsonb, '[스세꿘]', '[{"type": "명사", "definition": "스타벅스가 걸어갈 거리에 있는 주거지. 커피 한 잔의 문제라기보다, 스타벅스가 들어올 만큼 상권이 발달한 동네라는 신호로 읽힌다.", "definition_i18n": {"en": "A home within walking distance of a Starbucks. Less about the coffee than the signal: Starbucks opens where the commercial district is doing well.", "ja": "スターバックスが徒歩圏にある住まい。コーヒーというより、スタバが出店するほど商圏が発達した町だという記号として読まれる。", "es": "Una vivienda a pie de un Starbucks. Más que el café, es la señal: Starbucks abre donde la zona comercial funciona.", "vi": "Chỗ ở trong tầm đi bộ tới Starbucks. Không hẳn vì cà phê mà vì tín hiệu: Starbucks mở ở nơi khu thương mại phát triển.", "de": "Eine Wohnlage in Gehweite eines Starbucks. Weniger wegen des Kaffees als wegen des Signals: Starbucks eröffnet dort, wo die Lage läuft."}, "examples": [{"kor": "스세권 아니면 안 살아, 나는.", "eng": "I won''t live anywhere that isn''t 스세권.", "ja": "스세권じゃないところには住まない。", "es": "Yo no vivo donde no sea 스세권.", "vi": "Không phải 스세권 thì tôi không ở.", "de": "Wo kein 스세권 ist, ziehe ich nicht hin."}]}]'::jsonb, '''역세권''(지하철역 도보권)에서 ''-세권''만 떨어져 나와 접미사처럼 쓰이며 만들어진 부동산·생활 신조어 계열의 하나로, 앞에 스타벅스를 붙인 말이다. 2010년대 후반 분양 마케팅과 언론 보도를 타고 계열 전체가 퍼졌고, 개별 단어의 최초 사용처는 확인되지 않는다.', '{"en": "One of the ''-세권'' family: 역세권 (''within walking distance of a subway station'') shed its ending, which now works as a suffix you attach to whatever matters nearby — here, a Starbucks. The family spread through late-2010s property marketing and news coverage; no first use is documented for the individual word.", "ja": "「역세권(駅の徒歩圏)」から「-세권」だけが切り離され接尾辞のように使われる不動産・生活新造語の一つで、前にスターバックスを付けた形。2010年代後半の分譲マーケティングと報道を通じて系列全体が広まり、個別の語の初出は確認されていない。", "es": "Uno de la familia ''-세권'': de 역세권 (''a poca distancia a pie del metro'') se desprendió la terminación, que ahora funciona como sufijo al que se antepone lo que importa cerca — aquí, un Starbucks. La familia se difundió con el marketing inmobiliario y la prensa de finales de los 2010; no se documenta el primer uso de cada palabra.", "vi": "Một từ trong họ ''-세권'': từ 역세권 (''trong tầm đi bộ tới ga tàu điện''), đuôi -세권 tách ra thành hậu tố gắn với tiện ích người ta quan tâm — ở đây là Starbucks. Cả họ từ lan rộng nhờ marketing bất động sản và báo chí cuối thập niên 2010; không xác định được lần dùng đầu tiên của từng từ.", "de": "Eines der ''-세권''-Wörter: Von 역세권 (''in Gehweite einer U-Bahn-Station'') löste sich die Endung und dient nun als Suffix, dem man die jeweils wichtige Einrichtung voranstellt — hier ein Starbucks. Die Wortfamilie verbreitete sich über Immobilienmarketing und Presse der späten 2010er; der Erstgebrauch einzelner Wörter ist nicht belegt."}'::jsonb, '부동산 매물 소개와 아파트 분양 광고에서 입지 장점을 한마디로 보여줄 때 쓰고, 일상 대화에서도 ''여기 스세권이야''처럼 쓴다. 같은 계열 단어가 계속 만들어지고 있어, 뜻을 모르면 앞 글자가 무엇의 준말인지부터 보면 된다.', '{"en": "Used in property listings and new-build ads to sum up a location in one word, and in everyday talk too: ''여기 스세권이야'' (''this place is 스세권''). New members of the family keep appearing — when you meet one, work out what the first syllable is short for.", "ja": "不動産の物件紹介やマンション分譲広告で立地の強みを一言で示すときに使い、日常会話でも「ここは스세권だ」のように使う。同系列の語が次々に作られるので、意味が分からないときはまず頭の字が何の略かを見ればよい。", "es": "Se usa en anuncios de pisos y de obra nueva para resumir la ubicación en una palabra, y también al hablar: ''esto es 스세권''. La familia no para de crecer: ante una nueva, mira de qué es abreviatura la primera sílaba.", "vi": "Dùng trong tin rao bất động sản và quảng cáo chung cư mới để gói gọn vị trí trong một từ, và cả trong nói chuyện: ''chỗ này là 스세권''. Họ từ này liên tục có thành viên mới — gặp từ lạ thì cứ xem âm đầu viết tắt cho cái gì.", "de": "Steht in Immobilienanzeigen und Neubauwerbung, um die Lage in einem Wort zu fassen, und ebenso im Alltag: ''hier ist 스세권''. Die Wortfamilie wächst ständig — bei einem neuen Wort schaut man, wofür die erste Silbe steht."}'::jsonb, array['슬세권','숲세권','편세권'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Starbucks zone"}, {"lang": "🇯🇵 JA", "text": "スタバが近い住宅地"}, {"lang": "🇨🇳 ZH", "text": "星巴克住宅区"}, {"lang": "🇻🇳 VI", "text": "Khu gần Starbucks"}, {"lang": "🇪🇸 ES", "text": "Zona Starbucks"}, {"lang": "🇩🇪 DE", "text": "Starbucks-Viertel"}]'::jsonb),
('262', '맥세권', 'Maek-Se-Gwon', 'new-slang', '맥도날드가 가까워 배달까지 되는 동네', '{"en": "A neighbourhood close enough to a McDonald''s to get delivery", "ja": "マックが近く配達も届く町", "es": "Un barrio con McDonald''s cerca y reparto incluido", "vi": "Khu gần McDonald''s, giao tận nơi được", "de": "Ein Viertel nah genug am McDonald''s für Lieferung"}'::jsonb, '[맥쎄꿘]', '[{"type": "명사", "definition": "맥도날드가 걸어갈 거리에 있거나 배달 권역에 드는 주거지. 24시간 매장과 맥딜리버리가 기준이라, 밤늦게도 먹을 게 온다는 뜻으로 통한다.", "definition_i18n": {"en": "A home within walking distance of a McDonald''s — or at least inside its delivery radius. The 24-hour stores and McDelivery are the point: food arrives even late at night.", "ja": "マクドナルドが徒歩圏にあるか、配達エリアに入る住まい。24時間店舗とマックデリバリーが基準で、夜遅くても食べ物が届くという意味で通じる。", "es": "Una vivienda a pie de un McDonald''s o dentro de su radio de reparto. La clave son los locales 24 h y el McDelivery: llega comida hasta de madrugada.", "vi": "Chỗ ở trong tầm đi bộ tới McDonald''s, hoặc ít nhất nằm trong bán kính giao hàng. Điểm chính là cửa hàng 24/7 và McDelivery: khuya vẫn có đồ ăn.", "de": "Eine Wohnlage in Gehweite eines McDonald''s oder wenigstens im Lieferradius. Entscheidend sind 24-Stunden-Filialen und McDelivery: Essen kommt auch spätnachts."}, "examples": [{"kor": "맥세권이라 새벽에도 배달 시킬 수 있어.", "eng": "It''s 맥세권, so I can order delivery even at 3am.", "ja": "맥세권だから明け方でも配達を頼める。", "es": "Es 맥세권: puedo pedir a domicilio hasta de madrugada.", "vi": "Là 맥세권 nên rạng sáng vẫn đặt giao được.", "de": "맥세권 — ich kann selbst nachts noch bestellen."}]}]'::jsonb, '''역세권''(지하철역 도보권)에서 ''-세권''만 떨어져 나와 접미사처럼 쓰이며 만들어진 부동산·생활 신조어 계열의 하나로, 앞에 맥도날드를 붙인 말이다. 2010년대 후반 분양 마케팅과 언론 보도를 타고 계열 전체가 퍼졌고, 개별 단어의 최초 사용처는 확인되지 않는다.', '{"en": "One of the ''-세권'' family: 역세권 (''within walking distance of a subway station'') shed its ending, which now works as a suffix you attach to whatever matters nearby — here, a McDonald''s. The family spread through late-2010s property marketing and news coverage; no first use is documented for the individual word.", "ja": "「역세권(駅の徒歩圏)」から「-세권」だけが切り離され接尾辞のように使われる不動産・生活新造語の一つで、前にマクドナルドを付けた形。2010年代後半の分譲マーケティングと報道を通じて系列全体が広まり、個別の語の初出は確認されていない。", "es": "Uno de la familia ''-세권'': de 역세권 (''a poca distancia a pie del metro'') se desprendió la terminación, que ahora funciona como sufijo al que se antepone lo que importa cerca — aquí, un McDonald''s. La familia se difundió con el marketing inmobiliario y la prensa de finales de los 2010; no se documenta el primer uso de cada palabra.", "vi": "Một từ trong họ ''-세권'': từ 역세권 (''trong tầm đi bộ tới ga tàu điện''), đuôi -세권 tách ra thành hậu tố gắn với tiện ích người ta quan tâm — ở đây là McDonald''s. Cả họ từ lan rộng nhờ marketing bất động sản và báo chí cuối thập niên 2010; không xác định được lần dùng đầu tiên của từng từ.", "de": "Eines der ''-세권''-Wörter: Von 역세권 (''in Gehweite einer U-Bahn-Station'') löste sich die Endung und dient nun als Suffix, dem man die jeweils wichtige Einrichtung voranstellt — hier ein McDonald''s. Die Wortfamilie verbreitete sich über Immobilienmarketing und Presse der späten 2010er; der Erstgebrauch einzelner Wörter ist nicht belegt."}'::jsonb, '부동산 매물 소개와 아파트 분양 광고에서 입지 장점을 한마디로 보여줄 때 쓰고, 일상 대화에서도 ''여기 맥세권이야''처럼 쓴다. 같은 계열 단어가 계속 만들어지고 있어, 뜻을 모르면 앞 글자가 무엇의 준말인지부터 보면 된다.', '{"en": "Used in property listings and new-build ads to sum up a location in one word, and in everyday talk too: ''여기 맥세권이야'' (''this place is 맥세권''). New members of the family keep appearing — when you meet one, work out what the first syllable is short for.", "ja": "不動産の物件紹介やマンション分譲広告で立地の強みを一言で示すときに使い、日常会話でも「ここは맥세권だ」のように使う。同系列の語が次々に作られるので、意味が分からないときはまず頭の字が何の略かを見ればよい。", "es": "Se usa en anuncios de pisos y de obra nueva para resumir la ubicación en una palabra, y también al hablar: ''esto es 맥세권''. La familia no para de crecer: ante una nueva, mira de qué es abreviatura la primera sílaba.", "vi": "Dùng trong tin rao bất động sản và quảng cáo chung cư mới để gói gọn vị trí trong một từ, và cả trong nói chuyện: ''chỗ này là 맥세권''. Họ từ này liên tục có thành viên mới — gặp từ lạ thì cứ xem âm đầu viết tắt cho cái gì.", "de": "Steht in Immobilienanzeigen und Neubauwerbung, um die Lage in einem Wort zu fassen, und ebenso im Alltag: ''hier ist 맥세권''. Die Wortfamilie wächst ständig — bei einem neuen Wort schaut man, wofür die erste Silbe steht."}'::jsonb, array['슬세권','숲세권','편세권'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "McDonald''s zone"}, {"lang": "🇯🇵 JA", "text": "マックが近い住宅地"}, {"lang": "🇨🇳 ZH", "text": "麦当劳住宅区"}, {"lang": "🇻🇳 VI", "text": "Khu gần McDonald''s"}, {"lang": "🇪🇸 ES", "text": "Zona McDonald''s"}, {"lang": "🇩🇪 DE", "text": "McDonald''s-Viertel"}]'::jsonb),
('263', '학세권', 'Hak-Se-Gwon', 'new-slang', '학교·학원이 모여 있는 동네', '{"en": "A neighbourhood packed with schools and cram schools", "ja": "学校や塾が集まる町", "es": "Un barrio lleno de colegios y academias", "vi": "Khu tập trung trường học và lớp học thêm", "de": "Ein Viertel voller Schulen und Paukschulen"}'::jsonb, '[학쎄꿘]', '[{"type": "명사", "definition": "학교와 학원이 가까이 모여 있어 아이 통학·통원이 편한 주거지. 교육열이 집값에 직접 반영되는 한국 부동산 시장을 그대로 보여주는 말이다.", "definition_i18n": {"en": "A home where schools and cram schools cluster nearby, so a child''s daily commute is short. The word maps Korea''s education fever straight onto property prices.", "ja": "学校と塾が近くに集まり、子どもの通学・通塾が楽な住まい。教育熱がそのまま住宅価格に反映される韓国の不動産市場を映す言葉。", "es": "Una vivienda con colegios y academias agrupados cerca, para que el trayecto del niño sea corto. La palabra traduce la fiebre educativa coreana en precio de la vivienda.", "vi": "Chỗ ở có trường học và trung tâm học thêm quây quần gần đó, con đi học gần. Từ này phản ánh cơn sốt giáo dục Hàn Quốc đi thẳng vào giá nhà.", "de": "Eine Wohnlage, in der Schulen und Paukschulen dicht beieinanderliegen — kurze Wege fürs Kind. Das Wort überträgt Koreas Bildungsfieber direkt auf die Immobilienpreise."}, "examples": [{"kor": "학세권이라 전셋값이 안 떨어져.", "eng": "It''s 학세권, so the rents never come down.", "ja": "학세권だからチョンセ価格が下がらない。", "es": "Es 학세권: los alquileres no bajan.", "vi": "Là 학세권 nên giá thuê không giảm.", "de": "학세권 — die Mieten geben einfach nicht nach."}]}]'::jsonb, '''역세권''(지하철역 도보권)에서 ''-세권''만 떨어져 나와 접미사처럼 쓰이며 만들어진 부동산·생활 신조어 계열의 하나로, 앞에 학교·학원을 붙인 말이다. 2010년대 후반 분양 마케팅과 언론 보도를 타고 계열 전체가 퍼졌고, 개별 단어의 최초 사용처는 확인되지 않는다.', '{"en": "One of the ''-세권'' family: 역세권 (''within walking distance of a subway station'') shed its ending, which now works as a suffix you attach to whatever matters nearby — here, schools and cram schools. The family spread through late-2010s property marketing and news coverage; no first use is documented for the individual word.", "ja": "「역세권(駅の徒歩圏)」から「-세권」だけが切り離され接尾辞のように使われる不動産・生活新造語の一つで、前に学校・塾を付けた形。2010年代後半の分譲マーケティングと報道を通じて系列全体が広まり、個別の語の初出は確認されていない。", "es": "Uno de la familia ''-세권'': de 역세권 (''a poca distancia a pie del metro'') se desprendió la terminación, que ahora funciona como sufijo al que se antepone lo que importa cerca — aquí, colegios y academias. La familia se difundió con el marketing inmobiliario y la prensa de finales de los 2010; no se documenta el primer uso de cada palabra.", "vi": "Một từ trong họ ''-세권'': từ 역세권 (''trong tầm đi bộ tới ga tàu điện''), đuôi -세권 tách ra thành hậu tố gắn với tiện ích người ta quan tâm — ở đây là trường học và trung tâm học thêm. Cả họ từ lan rộng nhờ marketing bất động sản và báo chí cuối thập niên 2010; không xác định được lần dùng đầu tiên của từng từ.", "de": "Eines der ''-세권''-Wörter: Von 역세권 (''in Gehweite einer U-Bahn-Station'') löste sich die Endung und dient nun als Suffix, dem man die jeweils wichtige Einrichtung voranstellt — hier Schulen und Paukschulen. Die Wortfamilie verbreitete sich über Immobilienmarketing und Presse der späten 2010er; der Erstgebrauch einzelner Wörter ist nicht belegt."}'::jsonb, '부동산 매물 소개와 아파트 분양 광고에서 입지 장점을 한마디로 보여줄 때 쓰고, 일상 대화에서도 ''여기 학세권이야''처럼 쓴다. 같은 계열 단어가 계속 만들어지고 있어, 뜻을 모르면 앞 글자가 무엇의 준말인지부터 보면 된다.', '{"en": "Used in property listings and new-build ads to sum up a location in one word, and in everyday talk too: ''여기 학세권이야'' (''this place is 학세권''). New members of the family keep appearing — when you meet one, work out what the first syllable is short for.", "ja": "不動産の物件紹介やマンション分譲広告で立地の強みを一言で示すときに使い、日常会話でも「ここは학세권だ」のように使う。同系列の語が次々に作られるので、意味が分からないときはまず頭の字が何の略かを見ればよい。", "es": "Se usa en anuncios de pisos y de obra nueva para resumir la ubicación en una palabra, y también al hablar: ''esto es 학세권''. La familia no para de crecer: ante una nueva, mira de qué es abreviatura la primera sílaba.", "vi": "Dùng trong tin rao bất động sản và quảng cáo chung cư mới để gói gọn vị trí trong một từ, và cả trong nói chuyện: ''chỗ này là 학세권''. Họ từ này liên tục có thành viên mới — gặp từ lạ thì cứ xem âm đầu viết tắt cho cái gì.", "de": "Steht in Immobilienanzeigen und Neubauwerbung, um die Lage in einem Wort zu fassen, und ebenso im Alltag: ''hier ist 학세권''. Die Wortfamilie wächst ständig — bei einem neuen Wort schaut man, wofür die erste Silbe steht."}'::jsonb, array['슬세권','숲세권','편세권'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "School zone (schools & academies)"}, {"lang": "🇯🇵 JA", "text": "学校・塾が近い住宅地"}, {"lang": "🇨🇳 ZH", "text": "学区房(近学校补习班)"}, {"lang": "🇻🇳 VI", "text": "Khu gần trường học"}, {"lang": "🇪🇸 ES", "text": "Zona escolar"}, {"lang": "🇩🇪 DE", "text": "Schul-Viertel"}]'::jsonb),
('264', '몰세권', 'Mol-Se-Gwon', 'new-slang', '대형 쇼핑몰이 걸어갈 거리인 동네', '{"en": "A neighbourhood within walking distance of a big mall", "ja": "大型モールが徒歩圏の町", "es": "Un barrio a pie de un gran centro comercial", "vi": "Khu đi bộ tới trung tâm mua sắm lớn", "de": "Ein Viertel in Gehweite einer großen Mall"}'::jsonb, '[몰세꿘]', '[{"type": "명사", "definition": "스타필드·롯데월드몰 같은 대형 쇼핑몰이 걸어갈 거리에 있는 주거지. 쇼핑만이 아니라 영화관·식당·실내 놀이터까지 한 건물에서 해결된다는 뜻이다.", "definition_i18n": {"en": "A home within walking distance of a big mall like Starfield or Lotte World Mall. Not just shopping — cinema, restaurants and indoor playgrounds all sit in one building.", "ja": "スターフィールドやロッテワールドモールのような大型モールが徒歩圏にある住まい。買い物だけでなく映画館・飲食店・屋内遊び場まで一棟で片づくという意味。", "es": "Una vivienda a pie de un gran centro comercial tipo Starfield o Lotte World Mall. No solo compras: cine, restaurantes y zona de juegos cubierta en el mismo edificio.", "vi": "Chỗ ở đi bộ được tới trung tâm mua sắm lớn như Starfield hay Lotte World Mall. Không chỉ mua sắm — rạp phim, nhà hàng, khu chơi trong nhà đều trong một tòa.", "de": "Eine Wohnlage in Gehweite einer großen Mall wie Starfield oder Lotte World Mall. Nicht nur Shopping — Kino, Restaurants und Indoor-Spielplatz stecken im selben Gebäude."}, "examples": [{"kor": "몰세권이라 주말에 비 와도 놀 데가 있어.", "eng": "It''s 몰세권 — even a rainy weekend has somewhere to go.", "ja": "몰세권だから週末に雨でも遊ぶ場所がある。", "es": "Es 몰세권: aunque llueva el finde, hay adónde ir.", "vi": "Là 몰세권 nên cuối tuần mưa vẫn có chỗ chơi.", "de": "몰세권 — auch bei Regen am Wochenende gibt es ein Ziel."}]}]'::jsonb, '''역세권''(지하철역 도보권)에서 ''-세권''만 떨어져 나와 접미사처럼 쓰이며 만들어진 부동산·생활 신조어 계열의 하나로, 앞에 대형 쇼핑몰을 붙인 말이다. 2010년대 후반 분양 마케팅과 언론 보도를 타고 계열 전체가 퍼졌고, 개별 단어의 최초 사용처는 확인되지 않는다.', '{"en": "One of the ''-세권'' family: 역세권 (''within walking distance of a subway station'') shed its ending, which now works as a suffix you attach to whatever matters nearby — here, a big shopping mall. The family spread through late-2010s property marketing and news coverage; no first use is documented for the individual word.", "ja": "「역세권(駅の徒歩圏)」から「-세권」だけが切り離され接尾辞のように使われる不動産・生活新造語の一つで、前に大型ショッピングモールを付けた形。2010年代後半の分譲マーケティングと報道を通じて系列全体が広まり、個別の語の初出は確認されていない。", "es": "Uno de la familia ''-세권'': de 역세권 (''a poca distancia a pie del metro'') se desprendió la terminación, que ahora funciona como sufijo al que se antepone lo que importa cerca — aquí, un gran centro comercial. La familia se difundió con el marketing inmobiliario y la prensa de finales de los 2010; no se documenta el primer uso de cada palabra.", "vi": "Một từ trong họ ''-세권'': từ 역세권 (''trong tầm đi bộ tới ga tàu điện''), đuôi -세권 tách ra thành hậu tố gắn với tiện ích người ta quan tâm — ở đây là trung tâm mua sắm lớn. Cả họ từ lan rộng nhờ marketing bất động sản và báo chí cuối thập niên 2010; không xác định được lần dùng đầu tiên của từng từ.", "de": "Eines der ''-세권''-Wörter: Von 역세권 (''in Gehweite einer U-Bahn-Station'') löste sich die Endung und dient nun als Suffix, dem man die jeweils wichtige Einrichtung voranstellt — hier ein großes Einkaufszentrum. Die Wortfamilie verbreitete sich über Immobilienmarketing und Presse der späten 2010er; der Erstgebrauch einzelner Wörter ist nicht belegt."}'::jsonb, '부동산 매물 소개와 아파트 분양 광고에서 입지 장점을 한마디로 보여줄 때 쓰고, 일상 대화에서도 ''여기 몰세권이야''처럼 쓴다. 같은 계열 단어가 계속 만들어지고 있어, 뜻을 모르면 앞 글자가 무엇의 준말인지부터 보면 된다.', '{"en": "Used in property listings and new-build ads to sum up a location in one word, and in everyday talk too: ''여기 몰세권이야'' (''this place is 몰세권''). New members of the family keep appearing — when you meet one, work out what the first syllable is short for.", "ja": "不動産の物件紹介やマンション分譲広告で立地の強みを一言で示すときに使い、日常会話でも「ここは몰세권だ」のように使う。同系列の語が次々に作られるので、意味が分からないときはまず頭の字が何の略かを見ればよい。", "es": "Se usa en anuncios de pisos y de obra nueva para resumir la ubicación en una palabra, y también al hablar: ''esto es 몰세권''. La familia no para de crecer: ante una nueva, mira de qué es abreviatura la primera sílaba.", "vi": "Dùng trong tin rao bất động sản và quảng cáo chung cư mới để gói gọn vị trí trong một từ, và cả trong nói chuyện: ''chỗ này là 몰세권''. Họ từ này liên tục có thành viên mới — gặp từ lạ thì cứ xem âm đầu viết tắt cho cái gì.", "de": "Steht in Immobilienanzeigen und Neubauwerbung, um die Lage in einem Wort zu fassen, und ebenso im Alltag: ''hier ist 몰세권''. Die Wortfamilie wächst ständig — bei einem neuen Wort schaut man, wofür die erste Silbe steht."}'::jsonb, array['슬세권','숲세권','편세권'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Mall zone"}, {"lang": "🇯🇵 JA", "text": "モールが近い住宅地"}, {"lang": "🇨🇳 ZH", "text": "商场住宅区"}, {"lang": "🇻🇳 VI", "text": "Khu gần trung tâm thương mại"}, {"lang": "🇪🇸 ES", "text": "Zona de centro comercial"}, {"lang": "🇩🇪 DE", "text": "Mall-Viertel"}]'::jsonb),
('265', '병세권', 'Byeong-Se-Gwon', 'new-slang', '큰 병원이 가까운 동네', '{"en": "A neighbourhood close to a major hospital", "ja": "大きな病院が近い町", "es": "Un barrio cerca de un gran hospital", "vi": "Khu gần bệnh viện lớn", "de": "Ein Viertel nah an einem großen Krankenhaus"}'::jsonb, '[병세꿘]', '[{"type": "명사", "definition": "종합병원이나 대학병원이 가까워 진료·응급 대응이 빠른 주거지. 고령 인구가 늘면서 집을 고르는 조건으로 자주 언급된다.", "definition_i18n": {"en": "A home near a general or university hospital, so care and emergencies are close at hand. Cited more and more as the population ages.", "ja": "総合病院や大学病院が近く、受診も救急対応も早い住まい。高齢人口が増えるにつれ住まい選びの条件としてよく挙がる。", "es": "Una vivienda cerca de un hospital general o universitario: consultas y urgencias a mano. Se menciona cada vez más según envejece la población.", "vi": "Chỗ ở gần bệnh viện đa khoa hay bệnh viện đại học, khám và cấp cứu đều nhanh. Càng được nhắc nhiều khi dân số già đi.", "de": "Eine Wohnlage nahe einem Allgemein- oder Universitätsklinikum — Behandlung und Notfälle sind nah. Wird mit alternder Bevölkerung immer öfter genannt."}, "examples": [{"kor": "부모님 모시니까 병세권부터 봤어.", "eng": "Since my parents live with us, 병세권 was the first thing I checked.", "ja": "親と暮らすから병세권を最初に見た。", "es": "Como vivo con mis padres, lo primero que miré fue 병세권.", "vi": "Vì sống với bố mẹ nên tôi xem 병세권 trước tiên.", "de": "Weil meine Eltern mit uns wohnen, war 병세권 mein erstes Kriterium."}]}]'::jsonb, '''역세권''(지하철역 도보권)에서 ''-세권''만 떨어져 나와 접미사처럼 쓰이며 만들어진 부동산·생활 신조어 계열의 하나로, 앞에 병원을 붙인 말이다. 2010년대 후반 분양 마케팅과 언론 보도를 타고 계열 전체가 퍼졌고, 개별 단어의 최초 사용처는 확인되지 않는다.', '{"en": "One of the ''-세권'' family: 역세권 (''within walking distance of a subway station'') shed its ending, which now works as a suffix you attach to whatever matters nearby — here, a hospital. The family spread through late-2010s property marketing and news coverage; no first use is documented for the individual word.", "ja": "「역세권(駅の徒歩圏)」から「-세권」だけが切り離され接尾辞のように使われる不動産・生活新造語の一つで、前に病院を付けた形。2010年代後半の分譲マーケティングと報道を通じて系列全体が広まり、個別の語の初出は確認されていない。", "es": "Uno de la familia ''-세권'': de 역세권 (''a poca distancia a pie del metro'') se desprendió la terminación, que ahora funciona como sufijo al que se antepone lo que importa cerca — aquí, un hospital. La familia se difundió con el marketing inmobiliario y la prensa de finales de los 2010; no se documenta el primer uso de cada palabra.", "vi": "Một từ trong họ ''-세권'': từ 역세권 (''trong tầm đi bộ tới ga tàu điện''), đuôi -세권 tách ra thành hậu tố gắn với tiện ích người ta quan tâm — ở đây là bệnh viện. Cả họ từ lan rộng nhờ marketing bất động sản và báo chí cuối thập niên 2010; không xác định được lần dùng đầu tiên của từng từ.", "de": "Eines der ''-세권''-Wörter: Von 역세권 (''in Gehweite einer U-Bahn-Station'') löste sich die Endung und dient nun als Suffix, dem man die jeweils wichtige Einrichtung voranstellt — hier ein Krankenhaus. Die Wortfamilie verbreitete sich über Immobilienmarketing und Presse der späten 2010er; der Erstgebrauch einzelner Wörter ist nicht belegt."}'::jsonb, '부동산 매물 소개와 아파트 분양 광고에서 입지 장점을 한마디로 보여줄 때 쓰고, 일상 대화에서도 ''여기 병세권이야''처럼 쓴다. 같은 계열 단어가 계속 만들어지고 있어, 뜻을 모르면 앞 글자가 무엇의 준말인지부터 보면 된다.', '{"en": "Used in property listings and new-build ads to sum up a location in one word, and in everyday talk too: ''여기 병세권이야'' (''this place is 병세권''). New members of the family keep appearing — when you meet one, work out what the first syllable is short for.", "ja": "不動産の物件紹介やマンション分譲広告で立地の強みを一言で示すときに使い、日常会話でも「ここは병세권だ」のように使う。同系列の語が次々に作られるので、意味が分からないときはまず頭の字が何の略かを見ればよい。", "es": "Se usa en anuncios de pisos y de obra nueva para resumir la ubicación en una palabra, y también al hablar: ''esto es 병세권''. La familia no para de crecer: ante una nueva, mira de qué es abreviatura la primera sílaba.", "vi": "Dùng trong tin rao bất động sản và quảng cáo chung cư mới để gói gọn vị trí trong một từ, và cả trong nói chuyện: ''chỗ này là 병세권''. Họ từ này liên tục có thành viên mới — gặp từ lạ thì cứ xem âm đầu viết tắt cho cái gì.", "de": "Steht in Immobilienanzeigen und Neubauwerbung, um die Lage in einem Wort zu fassen, und ebenso im Alltag: ''hier ist 병세권''. Die Wortfamilie wächst ständig — bei einem neuen Wort schaut man, wofür die erste Silbe steht."}'::jsonb, array['슬세권','숲세권','편세권'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Hospital zone"}, {"lang": "🇯🇵 JA", "text": "病院が近い住宅地"}, {"lang": "🇨🇳 ZH", "text": "医院住宅区"}, {"lang": "🇻🇳 VI", "text": "Khu gần bệnh viện"}, {"lang": "🇪🇸 ES", "text": "Zona de hospital"}, {"lang": "🇩🇪 DE", "text": "Klinik-Viertel"}]'::jsonb),
('266', '백세권', 'Baek-Se-Gwon', 'new-slang', '백화점이 가까운 동네', '{"en": "A neighbourhood close to a department store", "ja": "デパートが近い町", "es": "Un barrio cerca de unos grandes almacenes", "vi": "Khu gần trung tâm bách hóa", "de": "Ein Viertel nah an einem Kaufhaus"}'::jsonb, '[백쎄꿘]', '[{"type": "명사", "definition": "신세계·현대·롯데 같은 백화점이 가까운 주거지. 쇼핑 편의보다 \"백화점이 들어설 만한 동네\"라는 지위 표시로 더 자주 쓰인다. 100세를 뜻하는 ‘백세’와 헷갈리기 쉬워 문맥으로 구분한다.", "definition_i18n": {"en": "A home near a department store like Shinsegae, Hyundai or Lotte. Used less for the shopping than as a status marker: the kind of district a department store picks. Easily confused with 백세 (\"100 years old\"), so context decides.", "ja": "新世界・現代・ロッテなどのデパートが近い住まい。買い物の便より「デパートが出るような町」という格の表示として使われることが多い。「百歳」の백세と紛らわしく、文脈で判断する。", "es": "Una vivienda cerca de unos grandes almacenes (Shinsegae, Hyundai, Lotte). Menos por las compras que como marca de estatus: el tipo de zona que eligen los grandes almacenes. Se confunde con 백세 (\"cien años\"), así que manda el contexto.", "vi": "Chỗ ở gần trung tâm bách hóa như Shinsegae, Hyundai, Lotte. Dùng ít vì mua sắm mà nhiều như dấu hiệu đẳng cấp: khu mà bách hóa chọn mở. Dễ nhầm với 백세 (\"trăm tuổi\"), phải nhìn ngữ cảnh.", "de": "Eine Wohnlage nahe einem Kaufhaus wie Shinsegae, Hyundai oder Lotte. Weniger fürs Einkaufen als als Statusmarker: so ein Viertel wählt ein Kaufhaus. Leicht mit 백세 (\"hundert Jahre\") zu verwechseln — der Kontext entscheidet."}, "examples": [{"kor": "백세권 아파트라고 광고하던데 좀 멀더라.", "eng": "They advertised it as a 백세권 flat, but the store was a fair walk.", "ja": "백세권マンションと宣伝していたが結構遠かった。", "es": "Lo anunciaban como piso 백세권, pero quedaba lejos.", "vi": "Họ quảng cáo là căn hộ 백세권 mà đi khá xa.", "de": "Beworben als 백세권-Wohnung, aber der Weg war doch weit."}]}]'::jsonb, '''역세권''(지하철역 도보권)에서 ''-세권''만 떨어져 나와 접미사처럼 쓰이며 만들어진 부동산·생활 신조어 계열의 하나로, 앞에 백화점을 붙인 말이다. 2010년대 후반 분양 마케팅과 언론 보도를 타고 계열 전체가 퍼졌고, 개별 단어의 최초 사용처는 확인되지 않는다.', '{"en": "One of the ''-세권'' family: 역세권 (''within walking distance of a subway station'') shed its ending, which now works as a suffix you attach to whatever matters nearby — here, a department store. The family spread through late-2010s property marketing and news coverage; no first use is documented for the individual word.", "ja": "「역세권(駅の徒歩圏)」から「-세권」だけが切り離され接尾辞のように使われる不動産・生活新造語の一つで、前に百貨店を付けた形。2010年代後半の分譲マーケティングと報道を通じて系列全体が広まり、個別の語の初出は確認されていない。", "es": "Uno de la familia ''-세권'': de 역세권 (''a poca distancia a pie del metro'') se desprendió la terminación, que ahora funciona como sufijo al que se antepone lo que importa cerca — aquí, unos grandes almacenes. La familia se difundió con el marketing inmobiliario y la prensa de finales de los 2010; no se documenta el primer uso de cada palabra.", "vi": "Một từ trong họ ''-세권'': từ 역세권 (''trong tầm đi bộ tới ga tàu điện''), đuôi -세권 tách ra thành hậu tố gắn với tiện ích người ta quan tâm — ở đây là trung tâm bách hóa. Cả họ từ lan rộng nhờ marketing bất động sản và báo chí cuối thập niên 2010; không xác định được lần dùng đầu tiên của từng từ.", "de": "Eines der ''-세권''-Wörter: Von 역세권 (''in Gehweite einer U-Bahn-Station'') löste sich die Endung und dient nun als Suffix, dem man die jeweils wichtige Einrichtung voranstellt — hier ein Kaufhaus. Die Wortfamilie verbreitete sich über Immobilienmarketing und Presse der späten 2010er; der Erstgebrauch einzelner Wörter ist nicht belegt."}'::jsonb, '부동산 매물 소개와 아파트 분양 광고에서 입지 장점을 한마디로 보여줄 때 쓰고, 일상 대화에서도 ''여기 백세권이야''처럼 쓴다. 같은 계열 단어가 계속 만들어지고 있어, 뜻을 모르면 앞 글자가 무엇의 준말인지부터 보면 된다.', '{"en": "Used in property listings and new-build ads to sum up a location in one word, and in everyday talk too: ''여기 백세권이야'' (''this place is 백세권''). New members of the family keep appearing — when you meet one, work out what the first syllable is short for.", "ja": "不動産の物件紹介やマンション分譲広告で立地の強みを一言で示すときに使い、日常会話でも「ここは백세권だ」のように使う。同系列の語が次々に作られるので、意味が分からないときはまず頭の字が何の略かを見ればよい。", "es": "Se usa en anuncios de pisos y de obra nueva para resumir la ubicación en una palabra, y también al hablar: ''esto es 백세권''. La familia no para de crecer: ante una nueva, mira de qué es abreviatura la primera sílaba.", "vi": "Dùng trong tin rao bất động sản và quảng cáo chung cư mới để gói gọn vị trí trong một từ, và cả trong nói chuyện: ''chỗ này là 백세권''. Họ từ này liên tục có thành viên mới — gặp từ lạ thì cứ xem âm đầu viết tắt cho cái gì.", "de": "Steht in Immobilienanzeigen und Neubauwerbung, um die Lage in einem Wort zu fassen, und ebenso im Alltag: ''hier ist 백세권''. Die Wortfamilie wächst ständig — bei einem neuen Wort schaut man, wofür die erste Silbe steht."}'::jsonb, array['슬세권','숲세권','편세권'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Department-store zone"}, {"lang": "🇯🇵 JA", "text": "百貨店が近い住宅地"}, {"lang": "🇨🇳 ZH", "text": "百货店住宅区"}, {"lang": "🇻🇳 VI", "text": "Khu gần trung tâm bách hóa"}, {"lang": "🇪🇸 ES", "text": "Zona de grandes almacenes"}, {"lang": "🇩🇪 DE", "text": "Kaufhaus-Viertel"}]'::jsonb),
('267', '도세권', 'Do-Se-Gwon', 'new-slang', '도서관·큰 서점이 가까운 동네', '{"en": "A neighbourhood close to a library or big bookshop", "ja": "図書館や大型書店が近い町", "es": "Un barrio cerca de biblioteca o gran librería", "vi": "Khu gần thư viện hoặc nhà sách lớn", "de": "Ein Viertel nah an Bibliothek oder Buchladen"}'::jsonb, '[도세꿘]', '[{"type": "명사", "definition": "공공도서관이나 대형 서점이 가까운 주거지. 아이 공부방이자 어른 작업실로 쓸 공간이 집 밖에 있다는 뜻으로, 학세권과 함께 언급되는 경우가 많다.", "definition_i18n": {"en": "A home near a public library or a big bookshop — a study room for the kids and a workspace for adults, just outside the flat. Usually mentioned alongside 학세권.", "ja": "公共図書館や大型書店が近い住まい。子どもの勉強部屋であり大人の作業場でもある空間が家の外にあるという意味で、학세권と一緒に語られることが多い。", "es": "Una vivienda cerca de una biblioteca pública o gran librería: sala de estudio para los niños y espacio de trabajo para los adultos, fuera de casa. Suele mencionarse junto a 학세권.", "vi": "Chỗ ở gần thư viện công hay nhà sách lớn — phòng học cho trẻ, chỗ làm việc cho người lớn, ngay ngoài nhà. Thường được nhắc cùng 학세권.", "de": "Eine Wohnlage nahe öffentlicher Bibliothek oder großer Buchhandlung — Lernraum für die Kinder, Arbeitsplatz für die Erwachsenen, außerhalb der Wohnung. Wird meist zusammen mit 학세권 genannt."}, "examples": [{"kor": "도세권이라 주말마다 도서관에서 살아.", "eng": "It''s 도세권 — I basically live at the library on weekends.", "ja": "도세권だから週末は図書館に入り浸っている。", "es": "Es 도세권: los findes prácticamente vivo en la biblioteca.", "vi": "Là 도세권 nên cuối tuần tôi ở lì thư viện.", "de": "도세권 — am Wochenende wohne ich praktisch in der Bibliothek."}]}]'::jsonb, '''역세권''(지하철역 도보권)에서 ''-세권''만 떨어져 나와 접미사처럼 쓰이며 만들어진 부동산·생활 신조어 계열의 하나로, 앞에 도서관·대형 서점을 붙인 말이다. 2010년대 후반 분양 마케팅과 언론 보도를 타고 계열 전체가 퍼졌고, 개별 단어의 최초 사용처는 확인되지 않는다.', '{"en": "One of the ''-세권'' family: 역세권 (''within walking distance of a subway station'') shed its ending, which now works as a suffix you attach to whatever matters nearby — here, a library or a big bookshop. The family spread through late-2010s property marketing and news coverage; no first use is documented for the individual word.", "ja": "「역세권(駅の徒歩圏)」から「-세권」だけが切り離され接尾辞のように使われる不動産・生活新造語の一つで、前に図書館・大型書店を付けた形。2010年代後半の分譲マーケティングと報道を通じて系列全体が広まり、個別の語の初出は確認されていない。", "es": "Uno de la familia ''-세권'': de 역세권 (''a poca distancia a pie del metro'') se desprendió la terminación, que ahora funciona como sufijo al que se antepone lo que importa cerca — aquí, una biblioteca o una gran librería. La familia se difundió con el marketing inmobiliario y la prensa de finales de los 2010; no se documenta el primer uso de cada palabra.", "vi": "Một từ trong họ ''-세권'': từ 역세권 (''trong tầm đi bộ tới ga tàu điện''), đuôi -세권 tách ra thành hậu tố gắn với tiện ích người ta quan tâm — ở đây là thư viện hay nhà sách lớn. Cả họ từ lan rộng nhờ marketing bất động sản và báo chí cuối thập niên 2010; không xác định được lần dùng đầu tiên của từng từ.", "de": "Eines der ''-세권''-Wörter: Von 역세권 (''in Gehweite einer U-Bahn-Station'') löste sich die Endung und dient nun als Suffix, dem man die jeweils wichtige Einrichtung voranstellt — hier eine Bibliothek oder eine große Buchhandlung. Die Wortfamilie verbreitete sich über Immobilienmarketing und Presse der späten 2010er; der Erstgebrauch einzelner Wörter ist nicht belegt."}'::jsonb, '부동산 매물 소개와 아파트 분양 광고에서 입지 장점을 한마디로 보여줄 때 쓰고, 일상 대화에서도 ''여기 도세권이야''처럼 쓴다. 같은 계열 단어가 계속 만들어지고 있어, 뜻을 모르면 앞 글자가 무엇의 준말인지부터 보면 된다.', '{"en": "Used in property listings and new-build ads to sum up a location in one word, and in everyday talk too: ''여기 도세권이야'' (''this place is 도세권''). New members of the family keep appearing — when you meet one, work out what the first syllable is short for.", "ja": "不動産の物件紹介やマンション分譲広告で立地の強みを一言で示すときに使い、日常会話でも「ここは도세권だ」のように使う。同系列の語が次々に作られるので、意味が分からないときはまず頭の字が何の略かを見ればよい。", "es": "Se usa en anuncios de pisos y de obra nueva para resumir la ubicación en una palabra, y también al hablar: ''esto es 도세권''. La familia no para de crecer: ante una nueva, mira de qué es abreviatura la primera sílaba.", "vi": "Dùng trong tin rao bất động sản và quảng cáo chung cư mới để gói gọn vị trí trong một từ, và cả trong nói chuyện: ''chỗ này là 도세권''. Họ từ này liên tục có thành viên mới — gặp từ lạ thì cứ xem âm đầu viết tắt cho cái gì.", "de": "Steht in Immobilienanzeigen und Neubauwerbung, um die Lage in einem Wort zu fassen, und ebenso im Alltag: ''hier ist 도세권''. Die Wortfamilie wächst ständig — bei einem neuen Wort schaut man, wofür die erste Silbe steht."}'::jsonb, array['슬세권','숲세권','편세권'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Library zone"}, {"lang": "🇯🇵 JA", "text": "図書館が近い住宅地"}, {"lang": "🇨🇳 ZH", "text": "图书馆住宅区"}, {"lang": "🇻🇳 VI", "text": "Khu gần thư viện"}, {"lang": "🇪🇸 ES", "text": "Zona de biblioteca"}, {"lang": "🇩🇪 DE", "text": "Bibliotheks-Viertel"}]'::jsonb),
('268', '수세권', 'Su-Se-Gwon', 'new-slang', '강·호수·바다가 가까운 동네', '{"en": "A neighbourhood near a river, lake or the sea", "ja": "川・湖・海が近い町", "es": "Un barrio cerca de río, lago o mar", "vi": "Khu gần sông, hồ hay biển", "de": "Ein Viertel nah an Fluss, See oder Meer"}'::jsonb, '[수세꿘]', '[{"type": "명사", "definition": "한강이나 호수·바다가 가까워 물가 산책과 조망이 되는 주거지. 서울에서는 사실상 한강 조망을 가리키며, 같은 단지 안에서도 물이 보이는 동이 더 비싸다.", "definition_i18n": {"en": "A home near the Han River, a lake or the sea — waterside walks and a view. In Seoul it effectively means a Han River view, and inside one complex the blocks that see water cost more.", "ja": "漢江や湖・海が近く、水辺の散歩と眺望が得られる住まい。ソウルでは事実上「漢江ビュー」を指し、同じ団地でも水が見える棟のほうが高い。", "es": "Una vivienda cerca del río Han, un lago o el mar: paseo junto al agua y vistas. En Seúl equivale a vistas al Han, y dentro del mismo complejo los bloques con agua a la vista cuestan más.", "vi": "Chỗ ở gần sông Hàn, hồ hay biển — dạo ven nước và có tầm nhìn. Ở Seoul gần như đồng nghĩa với view sông Hàn, và trong cùng khu, tòa nhìn ra nước đắt hơn.", "de": "Eine Wohnlage nahe Han-Fluss, See oder Meer — Uferspaziergang und Aussicht. In Seoul heißt das praktisch Han-Blick, und im selben Komplex kosten die Blöcke mit Wasserblick mehr."}, "examples": [{"kor": "수세권이라 저녁마다 강변 걸어.", "eng": "It''s 수세권 — I walk along the river every evening.", "ja": "수세권だから毎晩川沿いを歩く。", "es": "Es 수세권: paseo por la ribera cada tarde.", "vi": "Là 수세권 nên chiều nào tôi cũng đi bộ ven sông.", "de": "수세권 — jeden Abend am Fluss entlang."}]}]'::jsonb, '''역세권''(지하철역 도보권)에서 ''-세권''만 떨어져 나와 접미사처럼 쓰이며 만들어진 부동산·생활 신조어 계열의 하나로, 앞에 강·호수·바다를 붙인 말이다. 2010년대 후반 분양 마케팅과 언론 보도를 타고 계열 전체가 퍼졌고, 개별 단어의 최초 사용처는 확인되지 않는다.', '{"en": "One of the ''-세권'' family: 역세권 (''within walking distance of a subway station'') shed its ending, which now works as a suffix you attach to whatever matters nearby — here, a river, lake or the sea. The family spread through late-2010s property marketing and news coverage; no first use is documented for the individual word.", "ja": "「역세권(駅の徒歩圏)」から「-세권」だけが切り離され接尾辞のように使われる不動産・生活新造語の一つで、前に川・湖・海を付けた形。2010年代後半の分譲マーケティングと報道を通じて系列全体が広まり、個別の語の初出は確認されていない。", "es": "Uno de la familia ''-세권'': de 역세권 (''a poca distancia a pie del metro'') se desprendió la terminación, que ahora funciona como sufijo al que se antepone lo que importa cerca — aquí, un río, un lago o el mar. La familia se difundió con el marketing inmobiliario y la prensa de finales de los 2010; no se documenta el primer uso de cada palabra.", "vi": "Một từ trong họ ''-세권'': từ 역세권 (''trong tầm đi bộ tới ga tàu điện''), đuôi -세권 tách ra thành hậu tố gắn với tiện ích người ta quan tâm — ở đây là sông, hồ hay biển. Cả họ từ lan rộng nhờ marketing bất động sản và báo chí cuối thập niên 2010; không xác định được lần dùng đầu tiên của từng từ.", "de": "Eines der ''-세권''-Wörter: Von 역세권 (''in Gehweite einer U-Bahn-Station'') löste sich die Endung und dient nun als Suffix, dem man die jeweils wichtige Einrichtung voranstellt — hier Fluss, See oder Meer. Die Wortfamilie verbreitete sich über Immobilienmarketing und Presse der späten 2010er; der Erstgebrauch einzelner Wörter ist nicht belegt."}'::jsonb, '부동산 매물 소개와 아파트 분양 광고에서 입지 장점을 한마디로 보여줄 때 쓰고, 일상 대화에서도 ''여기 수세권이야''처럼 쓴다. 같은 계열 단어가 계속 만들어지고 있어, 뜻을 모르면 앞 글자가 무엇의 준말인지부터 보면 된다.', '{"en": "Used in property listings and new-build ads to sum up a location in one word, and in everyday talk too: ''여기 수세권이야'' (''this place is 수세권''). New members of the family keep appearing — when you meet one, work out what the first syllable is short for.", "ja": "不動産の物件紹介やマンション分譲広告で立地の強みを一言で示すときに使い、日常会話でも「ここは수세권だ」のように使う。同系列の語が次々に作られるので、意味が分からないときはまず頭の字が何の略かを見ればよい。", "es": "Se usa en anuncios de pisos y de obra nueva para resumir la ubicación en una palabra, y también al hablar: ''esto es 수세권''. La familia no para de crecer: ante una nueva, mira de qué es abreviatura la primera sílaba.", "vi": "Dùng trong tin rao bất động sản và quảng cáo chung cư mới để gói gọn vị trí trong một từ, và cả trong nói chuyện: ''chỗ này là 수세권''. Họ từ này liên tục có thành viên mới — gặp từ lạ thì cứ xem âm đầu viết tắt cho cái gì.", "de": "Steht in Immobilienanzeigen und Neubauwerbung, um die Lage in einem Wort zu fassen, und ebenso im Alltag: ''hier ist 수세권''. Die Wortfamilie wächst ständig — bei einem neuen Wort schaut man, wofür die erste Silbe steht."}'::jsonb, array['슬세권','숲세권','편세권'], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Waterside zone (river/lake/sea)"}, {"lang": "🇯🇵 JA", "text": "水辺が近い住宅地"}, {"lang": "🇨🇳 ZH", "text": "临水住宅区"}, {"lang": "🇻🇳 VI", "text": "Khu ven sông/hồ/biển"}, {"lang": "🇪🇸 ES", "text": "Zona ribereña"}, {"lang": "🇩🇪 DE", "text": "Wassernähe-Viertel"}]'::jsonb);

